INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66743310', 66743310, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Peralatan Sistem Pemantauan Radiasi Lingkungan dan Keselamatan Operasional IPLR', 'Barang', 'E-Purchasing', 'Banten, Tangerang Selatan (Kota)', 3700000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Paket', 'Pengadaan peralatan untuk mendukung sistem pemantauan kontinyu radiasi lingkungan dan keselamatan operasional Instalasi Pengelolaan Limbah Radioaktif (IPLR), meliputi detektor laju dosis gamma lingkungan, detektor laju dosis gamma lingkungan terintegrasi parameter cuaca, gamma area monitor untuk gedung proses dan storage, alat pemantau kontinyu alpha-beta di udara, dan dosimeter termoluminesensi. Pekerjaan termasuk pengadaan barang, pengiriman, pemasangan/instalasi, integrasi sistem, pengujian fungsi, commissioning, pelatihan operator, dokumentasi teknis, dan garansi', 'Pengadaan peralatan sistem pemantauan radiasi lingkungan dan keselamatan operasional IPLR, terdiri atas: 3 unit detektor laju dosis gamma lingkungan outdoor dengan minimal 2 moda komunikasi (LAN dan jaringan seluler/data), masing-masing dilengkapi minimal 1 sensor gamma, 1 base unit, 1 pedestal, 1 set panel surya, 1 set baterai, dan 1 set regulator/controller; 1 unit detektor laju dosis gamma lingkungan outdoor terintegrasi 1 set weather station dengan minimal 5 parameter cuaca (kecepatan angin, arah angin, curah hujan, suhu, kelembapan); 3 unit gamma area monitor kontinyu, masing-masing terdiri atas minimal 1 monitor/display dan 1 detektor NaI(Tl) atau setara, dilengkapi alarm audio visual dan set point alarm; 1 unit alat pemantau kontinyu alpha-beta di udara tipe mobile/portable, catu daya 220–240 VAC 50 Hz, minimal 2 detector, moving filter, pompa sampling udara, trolley, dan detection head; serta 10 unit thermoluminescence dosimeter konfigurasi minimal 4 elemen atau setara. Termasuk pengiriman, instalasi, integrasi sistem, pengujian fungsi, commissioning, pelatihan operator, dokumentasi teknis, dan garansi minimal 12 bulan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2974758);
