INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66747235', 66747235, 'analyze_legacy', 'Badan Riset dan Inovasi Nasional', 'central', 'Deputi Bidang Infrastruktur Riset dan Inovasi', 'Pengadaan Mebel/Furnitur Ruang Command Center Lantai 13 BRIN Thamrin', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 2500000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan mebel/furnitur untuk Ruang Command Center Lantai 13 BRIN Thamrin guna mendukung fungsi koordinasi, pemantauan, pengendalian, rapat strategis, penerimaan tamu kedinasan, serta pelaksanaan kegiatan pimpinan dan unit terkait secara luring maupun hybrid. Paket pekerjaan mencakup penyediaan, pengiriman, penempatan, pemasangan, penyesuaian layout, dan finishing mebel/furnitur agar ruang siap digunakan secara optimal sesuai kebutuhan operasional.', 'Penyediaan mebel/furnitur ruang command center dalam 1 paket, yang secara umum meliputi furnitur utama dan pendukung seperti meja rapat/command desk, meja kerja, credenza, kursi kerja, kursi rapat, sofa/tamu bila diperlukan, meja kecil pendukung, lemari/penyimpanan, panel/interior pendukung, serta perlengkapan furnitur lain yang relevan sesuai kebutuhan tata ruang. Spesifikasi harus memperhatikan kualitas material, kekuatan konstruksi, kenyamanan, ergonomi, keamanan penggunaan, keserasian desain, kemudahan perawatan, dan kesesuaian ukuran dengan kondisi ruang. Termasuk pengiriman, instalasi, perakitan, penempatan pada lokasi, perapihan akhir, serta jaminan/garansi sesuai ketentuan', 500000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2978515);
