INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66744172', 66744172, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KAIMANA', 'Pengadaan software pendukung perwajahan publikasi BPS Kabupaten/Kota', 'Jasa Lainnya', 'Dikecualikan', 'Papua Barat, Kaimana (Kab.)', 7945000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PAKET, @ 7945000 )', '1. Pengadaan software pendukung perwajahan publikasi BPS Kabupaten/Kota ( 1, PAKET, @ 7945000 );', 'A. Aplikasi Tata Letak Publikasi (Desktop Publishing) Digunakan untuk menyusun layout buku, laporan, majalah, dan buletin. Mendukung manajemen halaman dalam jumlah besar (buku). Mampu mengelola tipografi tingkat lanjut, gaya paragraf (paragraph style), dan gaya karakter (character style). Mendukung master page dan penomoran halaman otomatis. Kemampuan ekspor ke format PDF siap cetak (High-Quality Print/Press Quality) dan PDF interaktif. B. Aplikasi Desain Berbasis Vektor (Vector Graphics Editor) Digunakan untuk pembuatan infografis, desain sampul (cover), logo, dan ilustrasi. Mendukung ruang warna CMYK dan RGB secara presisi. Tersedia fitur artboard untuk berbagai ukuran kanvas. Mendukung ekspor/impor berbagai format vektor (EPS, SVG, AI/CDR) dan raster (PNG, JPG, TIFF). C. Aplikasi Pengolah Gambar Raster/Foto (Photo Editor) Digunakan untuk penyuntingan manipulasi foto, perbaikan warna (color grading), dan cropping gambar untuk publikasi. Mendukung manajemen lapisan (layer), mask, dan adjustment layers. Mendukung resolusi tinggi untuk kebutuhan cetak (minimal 300 dpi). D. Aplikasi Pengolah Dokumen PDF Digunakan untuk menggabungkan (merge), memisahkan (split), mengompresi, dan mengedit file PDF. Mendukung optimasi PDF untuk kebutuhan publikasi website BPS. (Catatan: Spesifikasi di atas secara industri merujuk pada paket seperti Adobe Creative Cloud for Teams/Enterprise atau CorelDRAW Graphics Suite dipadukan dengan aplikasi PDF). 4. Spesifikasi Lisensi Jenis Lisensi: Lisensi resmi untuk institusi pemerintah/korporasi (Government/Commercial License), bukan lisensi edukasi atau home user. Model Lisensi: Berlangganan (Subscription) atau Perpetual (sesuaikan dengan ketersediaan anggaran, umumnya standar industri saat ini adalah subscription). Masa Berlaku: 1 (satu) tahun sejak lisensi diaktivasi (jika model berlangganan). Hak Akses: Setiap lisensi harus dapat diinstal atau diakses oleh akun resmi pegawai/institusi BPS Kabupaten/Kota yang bersangkutan. Pembaruan (Updates): Mendapatkan hak penuh untuk mengunduh pembaruan fitur dan keamanan terbaru selama masa lisensi aktif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2979554);
